create or replace view v_analytics as select line,"year",lost_customer_hours,LAG(lost_customer_hours,1) over (partition by line order by "year") previous_year_lch, Round(((lost_customer_hours-LAG(lost_customer_hours,1) over (partition by line order by "year"))/NULLIF(LAG(lost_customer_hours,1) over (partition by line order by "year"), 0)*100),2) AS yoy_change from v_perfomance_base;